// generated by bin/build.ts - do not edit, edit the .ts source
/**
 * Set a project up to keep a decision log.
 *
 *   node /path/to/bosun/bin/install.ts ~/work/some-project
 *   node /path/to/bosun/bin/install.ts ~/work/some-project --write
 *   node /path/to/bosun/bin/install.ts ~/work/some-project --agent codex --write
 *
 * --agent picks how the rule reaches the agent. claude is the default and the
 * strongest: a hook fires on every message and cannot be summarised away. The
 * file-based bindings are what other tools offer, and they are weaker - read
 * once, then drifting out of context - which the README says out loud.
 *
 * Without --write it only says what it would do. With it, it creates
 * decisions/ and adds the hook to that project's .claude/settings.json,
 * merging rather than replacing: an existing settings file keeps everything it
 * had, and an unrelated UserPromptSubmit hook is left alone beside ours.
 *
 * It refuses rather than guesses. A settings file it cannot parse, or one that
 * already registers a different bosun install, stops it with an explanation.
 */

import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
  copyFileSync,
  statSync,
  lstatSync,
  realpathSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { join, resolve, dirname, basename, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { SCRIPT_ROOT, unknownFlag } from "./paths.mjs";
import { isDirectRun } from "./paths.mjs";

                                                
                                                      
                                                                                  

const HOOK = join(SCRIPT_ROOT, "hook", "presence.sh");
const COMMAND = `sh ${JSON.stringify(HOOK)}`;

/**
 * Which presence.sh a registered hook command names, or null when it names
 * none this install can resolve.
 *
 * The same install writes its command in two forms - relative to the project
 * where the checkout is inside it, absolute where it is not - so comparing the
 * strings answers the wrong question. What matters is the file, and the file is
 * the same one either way.
 */
export function namedHook(command        , root        )                {
  const parsed = /^sh\s+(?:"([^"]*)"|'([^']*)'|(\S+))\s*$/.exec(command.trim());
  const named = parsed?.[1] ?? parsed?.[2] ?? parsed?.[3];
  if (!named) return null;
  // Marked, not substituted, before the guard runs: putting the root in first
  // reintroduces a $ wherever the project path contains one, and the guard then
  // rejected this install's own hook - so every run appended the registration
  // again, which is exactly what reconcile exists to prevent.
  const HERE = "\u0000";
  const marked = named.replaceAll(/\$\{?CLAUDE_PROJECT_DIR\}?/g, HERE);
  // A command still carrying a variable this install cannot resolve is not a
  // file it may claim as its own.
  if (marked.includes("$")) return null;
  return resolve(root, marked.replaceAll(HERE, root));
}

/**
 * The same file, asked of the filesystem rather than of two strings.
 *
 * realpathSync resolves symlinks and leaves case alone, and the filesystem
 * under this tool is usually case-insensitive: a project named in the wrong
 * case compared unequal to itself, so an adopter was told their own working
 * hook belonged to a different install. Inode and device are the question that
 * was actually being asked.
 */
function sameFile(one               , other        )          {
  if (!one) return false;
  try {
    const here = statSync(one);
    const there = statSync(other);
    return here.ino === there.ino && here.dev === there.dev;
  } catch {
    return false;
  }
}

/** Is this registration this very checkout, whichever form it is written in? */
function isOurs(command        , root        )          {
  return sameFile(namedHook(command, root), HOOK);
}

/**
 * The hook command for one project.
 *
 * An absolute path is a machine, not a project: the same settings.json is
 * committed, cloned onto a second machine or into a colleague\'s checkout, and
 * names a directory that is not there - a hook that fails on every message.
 * When the bosun checkout sits inside the project (a submodule, a vendored
 * copy, a sibling under one working directory that is itself the project),
 * $CLAUDE_PROJECT_DIR makes the command travel with the file. Claude sets that
 * variable for every hook it runs; it is not our invention.
 *
 * Outside the project there is nothing to be relative to, and the absolute
 * path stays.
 */
export function hookCommand(root        )         {
  // Walked from the hook upward and asked of the filesystem at each step,
  // rather than measured between two strings. realpathSync resolves symlinks
  // and leaves case alone, and the filesystem under this tool is usually
  // case-insensitive, so a project named in another case measured as outside
  // itself and the absolute path was written with no word said - the failure
  // this whole function exists to prevent, reintroduced by the comparison
  // meant to fix it. Inode and device answer the question directly.
  const segments = [basename(HOOK)];
  let dir = dirname(HOOK);
  for (;;) {
    if (sameFile(dir, root)) {
      return `sh "$CLAUDE_PROJECT_DIR/${segments.join("/")}"`;
    }
    const up = dirname(dir);
    // The filesystem root, reached without ever meeting the project: the
    // checkout is outside it, and there is nothing to be relative to.
    if (up === dir) return COMMAND;
    segments.unshift(basename(dir));
    dir = up;
  }
}
const SKILL = join(SCRIPT_ROOT, "skill", "SKILL.md");
const DIST = join(SCRIPT_ROOT, "dist");

/** Where each tool reads a standing instruction from. */
const AGENTS                                                        = {
  claude: { file: null, what: "a hook that fires on every message" },
  codex: { file: "AGENTS.md", what: "a section in AGENTS.md" },
  cursor: { file: ".cursorrules", what: "a section in .cursorrules" },
  print: { file: null, what: "printed, for pasting wherever your tool reads" },
};

const MARK_START = "<!-- bosun:start -->";
const MARK_END = "<!-- bosun:end -->";

/** The rule as text, for tools that have no hook. */
function ruleText()         {
  const emitted = spawnSync("sh", [HOOK], { encoding: "utf8" });
  return (emitted.stdout ?? "").trim();
}

/**
 * Replace an existing bosun block or append a new one. Everything outside the
 * markers is left exactly as it was: this file belongs to the project.
 */
export function spliceRule(held        , rule        )         {
  const block = `${MARK_START}\n${rule}\n${MARK_END}`;
  const start = held.indexOf(MARK_START);
  const end = held.indexOf(MARK_END);
  if (start !== -1 && end !== -1) {
    return held.slice(0, start) + block + held.slice(end + MARK_END.length);
  }
  return held.trim() ? `${held.trimEnd()}\n\n${block}\n` : `${block}\n`;
}

/**
 * Whether the bosun markers already in a rule file are in a state spliceRule
 * can act on without guessing. A clean file (no markers) is appended to; one
 * well-formed block - a start, then an end - is replaced in place. Anything
 * else makes spliceRule silently delete or duplicate the owner's text: a lone
 * start plus the block a first run appends leaves two starts, and the next run
 * slices from the first start to the appended end, taking everything between
 * with it; an end before its start duplicates the span between them. The file
 * belongs to the project, so an ambiguous marker state is refused rather than
 * repaired, the same rule the settings file already follows.
 */
export function markerProblem(held        )                {
  const starts = held.split(MARK_START).length - 1;
  const ends = held.split(MARK_END).length - 1;
  if (starts === 0 && ends === 0) return null;
  if (
    starts === 1 &&
    ends === 1 &&
    held.indexOf(MARK_START) < held.indexOf(MARK_END)
  ) {
    return null;
  }
  return (
    `has bosun markers this install cannot resolve without guessing ` +
    `(${starts} start, ${ends} end` +
    (starts === 1 && ends === 1 ? ", out of order" : "") +
    `). This install will not rewrite it.`
  );
}

/**
 * Where a write to `target` would actually land: the deepest existing
 * ancestor (or the target itself) resolved through symlinks, plus whatever
 * does not exist yet. Null when a symlink on the way resolves to nowhere.
 */
export function landsAt(target        )                {
  const missing           = [];
  let probe = target;
  for (;;) {
    try {
      lstatSync(probe);
      break;
    } catch {
      const up = dirname(probe);
      if (up === probe) return null;
      missing.unshift(basename(probe));
      probe = up;
    }
  }
  try {
    return join(realpathSync(probe), ...missing);
  } catch {
    return null; // a symlink pointing at nothing
  }
}

/**
 * A settings.json, skill file or rules file that is a symlink out of the
 * project would get the *target* rewritten wholesale - a file this install
 * was never pointed at. Writing inside the project, or refusing, are the only
 * two outcomes. A symlink that stays inside the project is left to work.
 */
export function escapesProject(root        , target        )                {
  const real = realpathSync(root);
  const landing = landsAt(target);
  if (landing === null) {
    return `${target} is a symlink that resolves to nothing`;
  }
  if (landing !== real && !landing.startsWith(real + sep)) {
    return `${target} resolves to ${landing}, outside ${real}`;
  }
  return null;
}

/**
 * Whether the `node` on PATH can actually run the scripts.
 *
 * The version was the wrong thing to measure, twice over. It measured the
 * interpreter running this installer, which is not the one the hook's printed
 * commands will use; and a version is not the condition. A distribution build
 * of Node 22.22 without the TypeScript stripper passes any version gate and
 * then refuses every script with ERR_NO_TYPESCRIPT. Found by somebody
 * installing this on a machine where both `node` binaries were such builds.
 *
 * So it asks the binary the commands will name, and asks it the real question.
 */
export function nodeProblem()                {
  const asked = spawnSync("node", ["-p", "process.versions.node"], {
    encoding: "utf8",
  });

  if (asked.error || asked.status !== 0) {
    return `no usable \`node\` on PATH. The hook and the skill both name plain ` +
      `\`node\`, so that is the one that has to work.`;
  }

  const version = asked.stdout.trim();
  const [major = 0] = version.split(".").map(Number);
  if (major < 18) {
    return `the \`node\` on PATH is ${version}; the shipped scripts need 18 or ` +
      `newer.`;
  }
  return null;
}

export function settingsProblems(raw         )           {
  const plain = (value         )          =>
    value !== null && typeof value === "object" && !Array.isArray(value);

  if (!plain(raw)) {
    return [
      `it is ${Array.isArray(raw) ? "an array" : `a ${raw === null ? "null" : typeof raw}`}, ` +
        `not an object. This install will not rewrite it.`,
    ];
  }

  const settings = raw                           ;
  if (!("hooks" in settings)) return [];
  if (!plain(settings.hooks)) {
    return [`its "hooks" is not an object. This install will not rewrite it.`];
  }

  const groups = (settings.hooks                           ).UserPromptSubmit;
  if (groups === undefined) return [];
  if (!Array.isArray(groups)) {
    return [`its "hooks.UserPromptSubmit" is not an array.`];
  }

  const problems           = [];
  groups.forEach((group, index) => {
    if (!plain(group)) {
      problems.push(`hooks.UserPromptSubmit[${index}] is not an object.`);
      return;
    }
    const held = (group                           ).hooks;
    if (held === undefined) return;
    if (!Array.isArray(held)) {
      problems.push(`hooks.UserPromptSubmit[${index}].hooks is not an array.`);
      return;
    }
    // The array is not enough: otherInstall and reconcile read .command off
    // each entry, so a null or a bare value there is a stack trace over the
    // owner's file, not a merge. Checking the container and not its contents
    // was the twin left open. .command is the only field either function
    // reads, and otherInstall calls .includes on it, so a present non-string
    // is the same crash one level deeper - checked here rather than nowhere.
    held.forEach((hook, hookIndex) => {
      const at = `hooks.UserPromptSubmit[${index}].hooks[${hookIndex}]`;
      if (!plain(hook)) {
        problems.push(`${at} is not an object.`);
        return;
      }
      const command = (hook                           ).command;
      if (command !== undefined && typeof command !== "string") {
        problems.push(`${at}.command is not a string.`);
      }
    });
  });
  return problems;
}

/** A different install of the same hook is a conflict, not a duplicate. */
export function otherInstall(
  settings          ,
  ours = COMMAND,
  root         ,
)                {
  const groups = settings.hooks?.UserPromptSubmit ?? [];
  for (const group of groups) {
    for (const hook of group.hooks ?? []) {
      const command = hook.command ?? "";
      if (!command.includes("presence.sh") || command === ours) continue;
      // This checkout, written in the other form, is not a different install.
      // Refusing it there blocked every existing adopter from re-running the
      // installer - which is how the skill copy is refreshed - and told them
      // to remove a hook that was their own.
      if (root && isOurs(command, root)) continue;
      return command;
    }
  }
  return null;
}

/**
 * Every registration of this checkout reduced to one, in the current form.
 *
 * Null when the file already holds exactly that and there is nothing to do.
 * The earlier shape modelled at most one registration of ours and was wrong
 * twice over: a file holding both forms was reported as already registered and
 * the stale one was left to fail on every other machine, and a second
 * differently spelled one survived every run. Both meant the hook fired more
 * than once on every message, forever.
 *
 * A group left with no hooks is dropped rather than kept empty; nothing else
 * in the file is touched.
 */
export function reconcile(
  settings          ,
  command        ,
  root        ,
)                                               {
  const had           = [];
  let kept = false;
  const groups              = [];

  for (const group of settings.hooks?.UserPromptSubmit ?? []) {
    const hooks         = [];
    let dropped = false;
    for (const hook of group.hooks ?? []) {
      const held = hook.command ?? "";
      // Exact equality first: what this install writes is its own by
      // definition, and asking the filesystem about it can only go wrong.
      if (held !== command && !isOurs(held, root)) {
        hooks.push(hook);
        continue;
      }
      had.push(held);
      // The first one carries the registration forward, in the current form;
      // every further one is this same hook a second time.
      if (kept) {
        dropped = true;
        continue;
      }
      kept = true;
      hooks.push(held === command ? hook : { ...hook, command });
    }
    // Emptied by us, so it was ours to remove. A group that arrived empty
    // belongs to whoever wrote it: dropping that one deleted somebody else\'s
    // entry while the step above promised to keep everything else.
    if (dropped && hooks.length === 0) continue;
    groups.push({ ...group, ...(group.hooks === undefined ? {} : { hooks }) });
  }

  if (had.length === 1 && had[0] === command) return null;
  if (!kept) groups.push({ hooks: [{ type: "command", command }] });
  return {
    settings: { ...settings, hooks: { ...(settings.hooks ?? {}), UserPromptSubmit: groups } },
    had,
  };
}

function main(argv          )         {
  const unknown = unknownFlag(argv, ["--write", "--agent"]);
  if (unknown) {
    console.error(`refused: unknown flag ${unknown}`);
    return 1;
  }
  const write = argv.includes("--write");
  const agentIndex = argv.indexOf("--agent");
  const agent = agentIndex === -1 ? "claude" : argv[agentIndex + 1];
  // Object.hasOwn, not AGENTS[agent]: --agent toString or constructor would
  // otherwise resolve to an inherited property, pass the guard, and run with a
  // binding whose file and description are undefined.
  if (!Object.hasOwn(AGENTS, agent)) {
    console.error(
      `unknown --agent ${agent}; known: ${Object.keys(AGENTS).join(", ")}`,
    );
    return 1;
  }
  // Without --agent the index is -1, and skipping index 0 would drop the
  // target itself.
  const target = argv
    .filter((one, index) => agentIndex === -1 || index !== agentIndex + 1)
    .find((one) => !one.startsWith("--"));
  if (!target) {
    console.error("usage: install.ts <project directory> [--write]");
    return 1;
  }

  const root = resolve(target);
  if (!existsSync(root) || !statSync(root).isDirectory()) {
    console.error(`not a directory: ${root}`);
    return 1;
  }

  // Asked before anything is written: an install that lands fine and then
  // fails at every command is worse than one that says so up front.
  const unusable = nodeProblem();
  if (unusable) {
    console.error(`refused: ${unusable}`);
    return 1;
  }

  // print exists to hand the rule over, so it always prints it. It used to
  // sit behind the install steps and answered "nothing to do" on any project
  // already set up - which is exactly when somebody wants the text to paste
  // into a tool this installer does not know.
  if (agent === "print") {
    console.log(ruleText());
    return 0;
  }

  // The hook command lands in settings.json and is run by a shell; a $, a
  // backtick or a quote in the install path would be evaluated there, in
  // every adopting project, on every message. HOOK, not the finished command:
  // the relative form puts a $CLAUDE_PROJECT_DIR in there deliberately, and
  // testing the command would refuse the very thing it is meant to write.
  if (agent === "claude" && /[`$\\"\n\r]/.test(HOOK)) {
    console.error(
      `refused: the bosun install path contains characters a shell would ` +
        `evaluate inside the hook command:\n  ${SCRIPT_ROOT}\nMove the ` +
        `checkout to a plain path and run again.`,
    );
    return 1;
  }

  const decisions = join(root, "decisions");
  const settingsDir = join(root, ".claude");
  const settingsPath = join(settingsDir, "settings.json");

  // Only the claude path reads, validates or merges settings.json. A codex or
  // cursor install writes a rule file and never touches it, so reading it there
  // only invents ways to refuse a job it has no part in - a malformed or oddly
  // shaped settings.json blocking an AGENTS.md write, and, for a symlinked one,
  // reading outside the project a path that is never escape-checked for them.
  let settings           = {};
  if (agent === "claude" && existsSync(settingsPath)) {
    try {
      settings = JSON.parse(readFileSync(settingsPath, "utf8"))            ;
    } catch (error) {
      console.error(
        `refused: ${settingsPath} is not valid JSON ` +
          `(${(error         ).message}). Fix or move it, then run again.`,
      );
      return 1;
    }
  }

  // Shape before anything else: the merge below spreads and iterates, and
  // both operations quietly destroyed a file that was valid JSON of the wrong
  // shape.
  const shape = settingsProblems(settings);
  if (shape.length) {
    console.error(`refused: ${settingsPath} is not a settings file bosun can`);
    for (const problem of shape) console.error(`  ${problem}`);
    console.error("  Fix or move it, then run again.");
    return 1;
  }

  const command = hookCommand(root);
  const conflict = otherInstall(settings, command, root);
  if (conflict) {
    console.error(
      `refused: this project already registers a different bosun:\n  ` +
        `${conflict}\nRemove it first, or keep it and skip this install.`,
    );
    return 1;
  }

  const binding = AGENTS[agent];
  const rulePath = binding.file ? join(root, binding.file) : null;
  const skillPath = join(settingsDir, "skills", "bosun", "SKILL.md");

  // Everything this run might write must land inside the project.
  const writes =
    agent === "claude"
      ? [decisions, settingsPath, skillPath]
      : [decisions, ...(rulePath ? [rulePath] : [])];
  for (const one of writes) {
    const escape = escapesProject(root, one);
    if (escape) {
      console.error(
        `refused: ${escape}. This install writes inside the project it was ` +
          `pointed at, or not at all.`,
      );
      return 1;
    }
  }

  const steps           = [];
  if (!existsSync(decisions)) steps.push(`create ${decisions}`);

  const plan = agent === "claude" ? reconcile(settings, command, root) : null;

  if (agent === "claude") {
    if (!plan) {
      console.log(`already registered in ${settingsPath}`);
    } else if (plan.had.length) {
      // Said apart, because they are different faults with different fixes and
      // one message for both stated the wrong one: duplicates of the current
      // form are not written "in a form this install no longer writes".
      const stale = plan.had.filter((one) => one !== command).length;
      const over = plan.had.length - 1;
      const duplicates = over
        ? `${over} duplicate registration${over > 1 ? "s" : ""} of it`
        : "";
      steps.push(
        stale
          ? `settle the hook in ${settingsPath}: it names this same bosun in a ` +
            `form this install no longer writes` +
            (duplicates ? `, and holds ${duplicates}` : "")
          : `remove ${duplicates} from ${settingsPath}`,
      );
    } else {
      steps.push(
        existsSync(settingsPath)
          ? `add the hook to ${settingsPath}, keeping everything else`
          : `create ${settingsPath} with the hook`,
      );
    }
    steps.push(`copy the skill to ${skillPath}`);
  } else if (rulePath) {
    if (existsSync(rulePath)) {
      const marker = markerProblem(readFileSync(rulePath, "utf8"));
      if (marker) {
        console.error(`refused: ${rulePath} ${marker}`);
        console.error("  Resolve the bosun markers by hand, then run again.");
        return 1;
      }
    }
    steps.push(
      existsSync(rulePath)
        ? `put the rule in ${rulePath}, between bosun markers, leaving the ` +
          `rest of the file alone`
        : `create ${rulePath} with the rule`,
    );
  }

  if (steps.length === 0) {
    console.log("nothing to do; this project is set up");
    return 0;
  }

  console.log(`binding: ${binding.what}`);
  for (const step of steps) console.log(write ? "  " : "  would", step);

  if (!write) {
    console.log("\nRun again with --write to do it.");
    if (agent === "claude") console.log(`The hook will be: ${command}`);
    return 0;
  }

  if (!existsSync(decisions)) mkdirSync(decisions, { recursive: true });

  if (agent === "claude") {
    if (plan) {
      mkdirSync(settingsDir, { recursive: true });
      writeFileSync(
        settingsPath,
        JSON.stringify(plan.settings, null, 2) + "\n",
        "utf8",
      );
    }
    mkdirSync(dirname(skillPath), { recursive: true });
    copyFileSync(SKILL, skillPath);
  } else if (rulePath) {
    const held = existsSync(rulePath) ? readFileSync(rulePath, "utf8") : "";
    writeFileSync(rulePath, spliceRule(held, ruleText()), "utf8");
  }

  console.log(
    agent === "claude"
      ? `\nDone. Open a Claude Code session in ${root} and work as usual; ` +
          `run /hooks once, or restart the session, so the hook is loaded.\n` +
          `Nothing else is needed: the compressed layer and the fold only ` +
          `matter once there are entries to fold.`
      : `\nDone. The rule is a file this tool reads once per session, which is ` +
          `weaker than a hook that fires on every message: it can drift out of ` +
          `context in a long conversation. Re-run this after changing the ` +
          `rule, and it replaces the block between the markers.`,
  );
  // Said at the moment the path is written, not only in the README: a file a
  // team commits now names this machine's checkout, and the teammate who
  // clones it finds bindings pointing into somebody else's home directory.
  if ((agent === "claude" && command === COMMAND) || rulePath) {
    console.log(
      `note: what was written names this machine's bosun checkout. A ` +
        `teammate cloning ${basename(root)} re-runs this installer against ` +
        `their own checkout.`,
    );
  }
  return 0;
}

// realpathSync on both sides: Node canonicalises import.meta.url through
// symlinks but leaves process.argv[1] as typed, so reaching a script through
// a symlinked path (/tmp on macOS, a dotfile manager, a network home) made
// every one of these silently do nothing and exit 0. A save that reports
// success and records nothing is worse than one that crashes.
if (isDirectRun(import.meta.url)) {
  // The last net. This tool writes into somebody else's repository, so it
  // refuses by name rather than ending in a stack trace over their files.
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (error) {
    console.error("refused:", (error         ).message);
    process.exitCode = 1;
  }
}
